        }),
      ),
    ).rejects.toThrow(/allows no more issues/);
  });

  it("emits issue.created with the persisted issue's fields", async () => {
    const received: unknown[] = [];
    const off = subscribe("issue.created", (payload) => {
      received.push(payload);
