async function requireParent(
  orgId: OrgId,
  projectId: ProjectId,
  parentId: IssueId,
): Promise<Issue> {
  const parent = await issueRepo.findIssueById(orgId, parentId);
  const found = requireFound(
    parent?.projectId === projectId ? parent : null,
    "Issue",
    parentId,
  );
  assertNotArchived("Issue", found.id, found);
  return found;
}

/** Walk the ancestors before checking depth, so a cycle is always a cycle. */
async function assertPlacement(
  issueId: IssueId | null,
  parent: Issue | null,
  subtreeHeight: number,
): Promise<void> {
  const subjectId = issueId ?? parent!.id;
  const seen = new Set<string>(issueId === null ? [] : [issueId]);
  let depth = 0;
  let ancestor = parent;
  while (ancestor !== null) {
    if (seen.has(ancestor.id)) {
      throw new IssueHierarchyError(subjectId, "cycle");
    }
    seen.add(ancestor.id);
    depth += 1;
    if (ancestor.parentId === null) break;
    const next = await issueRepo.findIssueById(ancestor.orgId, ancestor.parentId);
    ancestor = requireFound(
      next?.projectId === ancestor.projectId ? next : null,
      "Issue",
      ancestor.parentId,
    );
  }
  if (depth + subtreeHeight > MAX_SUB_ISSUE_DEPTH) {
    throw new IssueHierarchyError(subjectId, "too_deep");
  }
}

function subtreeHeight(issueId: IssueId, descendants: readonly Issue[]): number {
  const children = new Map<IssueId, IssueId[]>();
  for (const issue of descendants) {
    if (issue.parentId === null) continue;
    const siblings = children.get(issue.parentId) ?? [];
    siblings.push(issue.id);
    children.set(issue.parentId, siblings);
  }
  const pending = [{ id: issueId, depth: 0 }];
  const seen = new Set<IssueId>();
  let height = 0;
  while (pending.length > 0) {
    const current = pending.pop()!;
    if (seen.has(current.id)) throw new IssueHierarchyError(issueId, "cycle");
    seen.add(current.id);
    height = Math.max(height, current.depth);
    for (const child of children.get(current.id) ?? []) {
      pending.push({ id: child, depth: current.depth + 1 });
    }
  }
  return height;
}

/** Called only for an open issue that has just closed or been archived. */
async function announceCompletedParent(actor: Actor, before: Issue): Promise<void> {
  if (before.parentId === null || CLOSED_ISSUE_STATUSES.includes(before.status)) return;
  const parent = await issueRepo.findIssueById(before.orgId, before.parentId);
  if (!parent || parent.projectId !== before.projectId || parent.archivedAt !== null || parent.assigneeId === null) return;
  const rollup = await issueRepo.getIssueRollup(before.orgId, parent.id);
  if (rollup.open !== 0) return;

  await emit("issue.sub_issues_completed", {
    ...actorEnvelope(actor),
    issueId: parent.id,
    projectId: parent.projectId,
    assigneeId: parent.assigneeId,
  });
}

/**
 * Creates an issue after four gates: tenant scope, the `issue:create`
 * permission, a live parent project and the plan's per-project issue quota.
 * Only then is a number allocated and `issue.created` published — everything
 * reactive (notifications, search, webhooks, the audit log) hangs off that.
 */
export async function createIssue(
  actor: Actor,
  input: CreateIssueInput,
): Promise<Issue> {
  assertOrgScope(actor, input.orgId);

  const project = requireFound(
    await projectRepo.findProjectById(input.orgId, input.projectId),
    "Project",
    input.projectId,
  );
  assertNotArchived("Project", project.id, project);
  assertCan(actor, "issue:create", projectResource(project));

  if (input.parentId !== null) {
    const parent = await requireParent(input.orgId, input.projectId, input.parentId);
    await assertPlacement(null, parent, 0);
  }

  const org = requireFound(
    await orgRepo.findOrgById(input.orgId),
    "Organization",
    input.orgId,
  );
  const used = await issueRepo.countIssues(input.orgId, input.projectId);
  if (wouldExceedLimit(org.plan, "issuesPerProject", used)) {
    throw new Error(
      `Plan ${org.plan} allows no more issues in project ${project.key}`,
    );
  }

  const number = await issueRepo.nextIssueNumber(input.orgId, input.projectId);
  const issue = await issueRepo.insertIssue(input, actor.userId, number);

  await emit("issue.created", {
    ...actorEnvelope(actor),
    issueId: issue.id,
    projectId: issue.projectId,
    title: issue.title,
    assigneeId: issue.assigneeId,
    priority: issue.priority,
  });

  return issue;
}

