const TERMINAL_STATUSES: readonly IssueStatus[] = ["done", "canceled"];

/** Include archived nodes when walking edges, even if the caller hides them. */
function issueSubtreeIds(orgId: OrgId, issueId: IssueId): SQL {
  return sql`(
    with recursive subtree(id, project_id) as (
      select ${issues.id}, ${issues.projectId} from ${issues}
      where ${orgPredicate(issues.orgId, orgId)} and ${eq(issues.id, issueId)}
      union
      select child.id, child.project_id from issues as child
      join subtree on child.parent_id = subtree.id
      where child.org_id = ${orgId} and child.project_id = subtree.project_id
    )
    select id from subtree
  )`;
}

export async function listSubIssues(
  orgId: OrgId,
  issueId: IssueId,
): Promise<readonly Issue[]> {
  const rows = getDb()
    .select()
    .from(issues)
    .where(and(
      orgPredicate(issues.orgId, orgId),
      eq(issues.parentId, issueId),
      inArray(issues.id, issueSubtreeIds(orgId, issueId)),
      livePredicate(issues.archivedAt, {}),
    ))
    .orderBy(asc(issues.createdAt), asc(issues.number))
    .all();
  const labels = await listLabelsForIssues(orgId, rows.map((row) => row.id as IssueId));
  return rows.map((row) => toIssue(row, (labels[row.id] ?? []).map((label) => label.id)));
}

/** No page limit: depth validation and cascading must see the entire subtree. */
export async function listIssueDescendants(
  orgId: OrgId,
  issueId: IssueId,
): Promise<readonly Issue[]> {
  const rows = getDb()
    .select()
    .from(issues)
    .where(and(
      orgPredicate(issues.orgId, orgId),
      ne(issues.id, issueId),
      inArray(issues.id, issueSubtreeIds(orgId, issueId)),
    ))
    .all();
  return rows.map((row) => toIssue(row));
}

export async function getIssueRollup(
  orgId: OrgId,
  issueId: IssueId,
): Promise<IssueRollup> {
  const row = getDb()
    .select({
      total: count(),
      closed: sql<number>`coalesce(sum(case when ${inArray(issues.status, [...CLOSED_ISSUE_STATUSES])} then 1 else 0 end), 0)`,
    })
    .from(issues)
    .where(and(
      orgPredicate(issues.orgId, orgId),
      ne(issues.id, issueId),
      inArray(issues.id, issueSubtreeIds(orgId, issueId)),
      livePredicate(issues.archivedAt, {}),
    ))
    .get();
  const total = row?.total ?? 0;
  const closed = row?.closed ?? 0;
  return { total, open: total - closed, closed };
}

